using System;using System.Collections.Generic;public class IntervalHeap{private List<(int start, int end)> heap;public IntervalHeap(){heap=new List<(int start, int end)>();}public void Insert((int start, int end) interval){heap.Add(interval);HeapifyUp(heap.Count-1);}public (int start, int end) RemoveMin(){if(IsEmpty())throw new InvalidOperationException("Heap is empty.");var min=heap[0];heap[0]=heap[heap.Count-1];heap.RemoveAt(heap.Count-1);HeapifyDown(0);return min;}public bool IsEmpty(){return heap.Count==0;}public int Size(){return heap.Count;}private void HeapifyUp(int index){while(index>0){int parent=(index-1)/2;if(heap[index].start<heap[parent].start){Swap(index,parent);index=parent;}else break;}}private void HeapifyDown(int index){int leftChild=2*index+1;int rightChild=2*index+2;int smallest=index;if(leftChild<heap.Count&&heap[leftChild].start<heap[smallest].start)smallest=leftChild;if(rightChild<heap.Count&&heap[rightChild].start<heap[smallest].start)smallest=rightChild;if(smallest!=index){Swap(index,smallest);HeapifyDown(smallest);}}private void Swap(int i,int j){var temp=heap[i];heap[i]=heap[j];heap[j]=temp;}}